// Node "Code" (après Airtable Search)
// Compte le nombre d'items dont "Dort sur place ?" = "oui" (insensible à la casse)

const items = $input.all();

let countOui = 0;

for (const item of items) {
  const v = item.json?.["Dort sur place ?"];
  const s = (v ?? "").toString().trim().toLowerCase();
  if (s === "oui") countOui++;
}

return [
  {
    json: {
      totalItems: items.length,
      dortSurPlaceOui: countOui,
    },
  },
];

